Lemma U_general : forall (set full nolast : bool) (pfp dh dwpl dnf : Z) (g3 g4 : word) r0 m,
  ret_ok ret -> (1 <= dh <= 20000)%Z -> (1 <= dwpl < 2 ^ 24)%Z -> (0 <= dnf < 2 ^ 26)%Z -> (full = true -> (1 <= dnf)%Z) ->
