  (full = true -> getr r0 9 = Z_to_bv 64 (pfp + 4)) -> (nolast = false -> getr r0 20 = Z_to_bv 64 (pfp + 4 + (if full then 4 * dnf else 0))) ->
  UKF g3 g4 ->
